class BankAccount {
    protected String accountId;
    protected double balance;

    public BankAccount(String accountId, double initial) {
        this.accountId = accountId;
        this.balance = initial;
    }

    public void deposit(double amount) {
        this.balance += amount;
        System.out.println(accountId + " balance: $" + balance);
    }
}

// Sibling 1: Adds interest calculation
class SavingsAccount extends BankAccount {
    private double interestRate;
    public SavingsAccount(String id, double balance, double rate) {
        super(id, balance);
        this.interestRate = rate;
    }
    public void addInterest() {
        double interest = balance * (interestRate / 100.0);
        deposit(interest);
    }
}

// Sibling 2: Adds check writing fees
class CheckingAccount extends BankAccount {
    private double feePerCheck;
    public CheckingAccount(String id, double balance, double fee) {
        super(id, balance);
        this.feePerCheck = fee;
    }
    public void writeCheck(double amount) {
        balance -= (amount + feePerCheck);
        System.out.println(accountId + " check cleared for $" + amount + ". Balance: $" + balance);
    }
}

public class HierarchicalDemo {
    public static void main(String[] args) {
        SavingsAccount sav = new SavingsAccount("SAV-01", 1000.0, 4.0);
        CheckingAccount chk = new CheckingAccount("CHK-02", 500.0, 1.50);

        sav.addInterest(); // Legal on SavingsAccount
        chk.writeCheck(100.0); // Legal on CheckingAccount

        // COMPILER ERROR if attempted:
        // sav.writeCheck(50.0); // SavingsAccount has no writeCheck()!
    }
}

