class Notification {
    protected String recipient;
    protected String message;
    public Notification(String recipient, String message) {
        this.recipient = recipient;
        this.message = message;
    }
}

class EmailNotification extends Notification {
    private String subject;
    public EmailNotification(String recipient, String message, String subject) {
        super(recipient, message);
        this.subject = subject;
    }
    public void sendEmail() {
        System.out.println("Sending Email to " + recipient + " [Subject: " + subject + "]: " + message);
    }
}

class SmsNotification extends Notification {
    private int characterLimit;
    public SmsNotification(String recipient, String message, int charLimit) {
        super(recipient, message);
        this.characterLimit = charLimit;
    }
    public void sendSms() {
        System.out.println("Sending SMS to " + recipient + " (Max " + characterLimit + " chars): " + message);
    }
}

public class Main {
    public static void main(String[] args) {
        EmailNotification email = new EmailNotification("user@domain.com", "Password reset requested", "Security Alert");
        SmsNotification sms = new SmsNotification("+15550199", "Your verification code is 4491", 160);
        email.sendEmail();
        sms.sendSms();
    }
}

