class CloudBucket {
    protected String bucketName;
    protected String region;
    protected String storageClass;
    public CloudBucket(String name, String region, String storageClass) {
        this.bucketName = name;
        this.region = region;
        this.storageClass = storageClass;
    }
}

class S3Bucket extends CloudBucket {
    private boolean versioningEnabled;
    public S3Bucket(String name, String region, String storageClass, boolean versioning) {
        super(name, region, storageClass);
        this.versioningEnabled = versioning;
    }
    public void displaySpecs() {
        System.out.println("S3 Bucket [" + bucketName + "] in " + region + " (" + storageClass + ") - Versioning: " + versioningEnabled);
    }
}

class GcsBucket extends CloudBucket {
    private int retentionPeriodDays;
    public GcsBucket(String name, String region, String storageClass, int days) {
        super(name, region, storageClass);
        this.retentionPeriodDays = days;
    }
    public void displaySpecs() {
        System.out.println("GCS Bucket [" + bucketName + "] in " + region + " (" + storageClass + ") - Retention: " + retentionPeriodDays + " days");
    }
}

class AzureBlobBucket extends CloudBucket {
    private String accessTier;
    public AzureBlobBucket(String name, String region, String storageClass, String tier) {
        super(name, region, storageClass);
        this.accessTier = tier;
    }
    public void displaySpecs() {
        System.out.println("Azure Blob [" + bucketName + "] in " + region + " (" + storageClass + ") - Access Tier: " + accessTier);
    }
}

public class Main {
    public static void main(String[] args) {
        S3Bucket s3 = new S3Bucket("app-media-prod", "us-east-1", "STANDARD", true);
        GcsBucket gcs = new GcsBucket("analytics-data", "europe-west1", "COLDLINE", 90);
        AzureBlobBucket azure = new AzureBlobBucket("archive-store", "East US", "ARCHIVE", "Hot");
        s3.displaySpecs();
        gcs.displaySpecs();
        azure.displaySpecs();
    }
}
